#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Url {
    scheme: String,
    host: String,
    path: String,
    query: String,
}

impl Url {
    pub fn new(input: impl Into<String>) -> Self {
        Self::parse(&input.into())
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn query_params(&self) -> Vec<(String, String)> {
        self.query
            .split('&')
            .filter(|segment| !segment.is_empty())
            .map(|segment| match segment.split_once('=') {
                Some((key, value)) => (key.to_string(), value.to_string()),
                None => (segment.to_string(), String::new()),
            })
            .collect()
    }

    fn parse(input: &str) -> Self {
        let mut remaining = input;
        let mut scheme = String::new();

        if let Some(index) = remaining.find("://") {
            scheme = remaining[..index].to_string();
            remaining = &remaining[index + 3..];
        }

        let authority_end = remaining
            .find(|ch| matches!(ch, '/' | '?' | '#'))
            .unwrap_or(remaining.len());
        let authority = &remaining[..authority_end];
        remaining = &remaining[authority_end..];

        let mut path = String::new();
        if remaining.starts_with('/') {
            let path_end = remaining
                .find(|ch| matches!(ch, '?' | '#'))
                .unwrap_or(remaining.len());
            path = remaining[..path_end].to_string();
            remaining = &remaining[path_end..];
        }

        let mut query = String::new();
        if let Some(after_question_mark) = remaining.strip_prefix('?') {
            let query_end = after_question_mark.find('#').unwrap_or(after_question_mark.len());
            query = after_question_mark[..query_end].to_string();
        }

        Self {
            scheme,
            host: parse_host(authority),
            path,
            query,
        }
    }
}

fn parse_host(authority: &str) -> String {
    let without_userinfo = authority
        .rsplit_once('@')
        .map(|(_, host)| host)
        .unwrap_or(authority);

    if without_userinfo.starts_with('[') {
        if let Some(index) = without_userinfo.find(']') {
            return without_userinfo[..=index].to_string();
        }
    }

    if let Some((host, _port)) = without_userinfo.rsplit_once(':') {
        if !host.contains(':') {
            return host.to_string();
        }
    }

    without_userinfo.to_string()
}

